create table actividad (calificada boolean not null, nota_maxima numeric(5,2) not null, visible boolean not null, fecha_limite timestamp(6) not null, id_actividad bigint generated by default as identity, id_criterio bigint, id_semana bigint not null, tipo varchar(20) not null check ((tipo in ('TAREA','PC','PROYECTO','PRACTICA','EXAMEN'))), titulo varchar(100) not null, descripcion TEXT, primary key (id_actividad));
create table alerta_academica (fecha_alerta timestamp(6) not null, id_alerta bigint generated by default as identity, id_matricula bigint not null, tipo varchar(30) not null check ((tipo in ('BAJO_RENDIMIENTO','AUSENTISMO'))), descripcion TEXT, primary key (id_alerta));
create table asistencia (justificada boolean not null, id_asistencia bigint generated by default as identity, id_matricula bigint not null, id_sesion bigint not null, estado varchar(20) not null check ((estado in ('PRESENTE','TARDE','FALTA'))), primary key (id_asistencia));
create table contenido (visible boolean not null, fecha_publicacion timestamp(6) not null, id_contenido bigint generated by default as identity, id_semana bigint not null, tipo varchar(20) not null check ((tipo in ('PDF','VIDEO','ENLACE','ARCHIVO'))), titulo varchar(150) not null, descripcion TEXT, url_recurso varchar(255), primary key (id_contenido));
create table criterio_evaluacion (porcentaje numeric(5,2) not null, id_criterio bigint generated by default as identity, id_seccion bigint not null, nombre varchar(50) not null, primary key (id_criterio));
create table curso (creditos integer not null, id_curso bigint generated by default as identity, codigo varchar(20) not null unique, nombre varchar(100) not null, descripcion TEXT, primary key (id_curso));
create table docente (id_docente bigint generated by default as identity, id_usuario bigint not null unique, codigo_docente varchar(20) not null unique, especialidad varchar(100) not null, primary key (id_docente));
create table docente_seccion (id_docente bigint not null, id_docente_seccion bigint generated by default as identity, id_seccion bigint not null, primary key (id_docente_seccion));
create table entrega (nota numeric(5,2), fecha_entrega timestamp(6) not null, id_actividad bigint not null, id_entrega bigint generated by default as identity, id_matricula bigint not null, estado varchar(20) not null check ((estado in ('ENTREGADO','ATRASADO','CALIFICADO','REVISADO'))), archivo_url varchar(255), comentario_alumno TEXT, comentario_docente TEXT, primary key (id_entrega));
create table estudiante (id_estudiante bigint generated by default as identity, id_usuario bigint not null unique, codigo_estudiante varchar(20) not null unique, estado_academico varchar(20) not null check ((estado_academico in ('REGULAR','OBSERVADO','RETIRADO','CONDICIONADO'))), primary key (id_estudiante));
create table foro (creado_por bigint not null, fecha_creacion timestamp(6) not null, id_foro bigint generated by default as identity, id_semana bigint not null, titulo varchar(150) not null, mensaje_principal TEXT, primary key (id_foro));
create table foro_respuesta (fecha_respuesta timestamp(6) not null, id_foro bigint not null, id_respuesta bigint generated by default as identity, id_usuario bigint not null, mensaje TEXT, primary key (id_respuesta));
create table matricula (fecha_matricula timestamp(6) not null, id_estudiante bigint not null, id_matricula bigint generated by default as identity, id_seccion bigint not null, estado varchar(20) not null check ((estado in ('ACTIVO','RETIRADO','CONDICIONADO'))), primary key (id_matricula));
create table notificacion (leido boolean not null, fecha_envio timestamp(6) not null, id_notificacion bigint generated by default as identity, id_usuario bigint not null, titulo varchar(100) not null, mensaje TEXT, primary key (id_notificacion));
create table periodo_academico (fecha_fin date not null, fecha_inicio date not null, numero_semanas integer not null, id_periodo bigint generated by default as identity, estado varchar(20) not null check ((estado in ('ACTIVO','FINALIZADO'))), nombre varchar(50) not null, primary key (id_periodo));
create table permiso (id_permiso bigint generated by default as identity, accion varchar(50) not null, nombre varchar(100) not null, recurso varchar(100) not null, primary key (id_permiso));
create table rol (id_rol bigint generated by default as identity, nombre varchar(50) not null unique, primary key (id_rol));
create table rol_permiso (id_permiso bigint not null, id_rol bigint not null, id_rol_permiso bigint generated by default as identity, primary key (id_rol_permiso));
create table seccion (capacidad integer not null, id_curso bigint not null, id_periodo bigint not null, id_seccion bigint generated by default as identity, nombre varchar(20) not null, primary key (id_seccion));
create table semana_academica (numero_semana integer not null, id_seccion bigint not null, id_semana bigint generated by default as identity, titulo varchar(100) not null, primary key (id_semana));
create table sesion_clase (fecha date not null, id_semana bigint not null, id_sesion bigint generated by default as identity, tema varchar(150) not null, primary key (id_sesion));
create table subsanacion (nota_anterior numeric(5,2), nueva_nota numeric(5,2), fecha_subsanacion timestamp(6) not null, id_entrega bigint not null, id_subsanacion bigint generated by default as identity, motivo TEXT, primary key (id_subsanacion));
create table usuario (created_at timestamp(6) not null, id_usuario bigint generated by default as identity, estado varchar(20) not null check ((estado in ('ACTIVO','INACTIVO','BLOQUEADO'))), apellidos varchar(100) not null, nombres varchar(100) not null, email varchar(120) not null unique, password_hash varchar(255) not null, primary key (id_usuario));
create table usuario_rol (id_rol bigint not null, id_usuario bigint not null, id_usuario_rol bigint generated by default as identity, primary key (id_usuario_rol));
